import { sqrtPriceX96AtTick as sqrtRatioX96AtTick } from "../tickMath.js";

// LaunchPricing.sol's arithmetic, off chain: the tick a USD market cap sits at for a supply at a quote's price, and
// the window a pad's FDV range makes of it. Exact integer math, so a start tick is inside the window here exactly
// when the settings contract takes it. launchResolver.ts is built on it.

const MIN_TICK = -887_272;
const MAX_TICK = 887_272;
const MIN_SQRT_PRICE = 4_295_128_739n;
const MAX_SQRT_PRICE =
  1_461_446_703_485_210_103_287_273_052_203_988_822_378_723_970_342n;
const UINT256_MAX = (1n << 256n) - 1n;

/** OpenZeppelin `Math.sqrt`: the square root rounded down. */
function sqrtFloor(n: bigint): bigint {
  if (n < 2n) return n;
  let x = 1n << BigInt(Math.ceil(n.toString(2).length / 2));
  for (;;) {
    const y = (x + n / x) >> 1n;
    if (y >= x) return x;
    x = y;
  }
}

/** v4 `TickMath.getTickAtSqrtPrice`: the greatest tick whose sqrt price is at or under `sqrtPriceX96`. */
export function bankrV4TickAtSqrtPrice(sqrtPriceX96: bigint): number {
  let [lo, hi] = [MIN_TICK, MAX_TICK];
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (sqrtRatioX96AtTick(mid) <= sqrtPriceX96) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

/**
 * `LaunchPricing._fdvTick`: the tick at or below quote raw per token raw for a market cap of `fdvUsd` whole USD,
 * a quote of `decimals` priced at `priceUsdE18` and `supply` raw units; clamped to v4's range.
 */
export function bankrV4FdvTick(
  fdvUsd: bigint,
  decimals: number,
  priceUsdE18: bigint,
  supply: bigint,
): number {
  if (priceUsdE18 > UINT256_MAX / supply) return MIN_TICK;
  const num = fdvUsd * 10n ** BigInt(18 + decimals);
  const den = priceUsdE18 * supply;
  const whole = num / den;
  let sqrtP: bigint;
  if (whole < 1n << 64n) sqrtP = sqrtFloor((num << 192n) / den);
  else if (whole < 1n << 128n) sqrtP = sqrtFloor((num << 128n) / den) << 32n;
  else return MAX_TICK;
  if (sqrtP < MIN_SQRT_PRICE) return MIN_TICK;
  if (sqrtP >= MAX_SQRT_PRICE) return MAX_TICK;
  return bankrV4TickAtSqrtPrice(sqrtP);
}

/** The start ticks a pad's FDV range admits for `supply` at the quote's price (`settings.startTickBounds`). */
export function bankrV4StartWindow(i: {
  fdvUsd: { min: bigint; max: bigint };
  decimals: number;
  priceUsdE18: bigint;
  supply: bigint;
}): { lowest: number; highest: number } {
  const at = (fdv: bigint) =>
    bankrV4FdvTick(fdv, i.decimals, i.priceUsdE18, i.supply);
  return { lowest: at(i.fdvUsd.min), highest: at(i.fdvUsd.max) };
}
